// Terminal.tsx
'use client';
import React, { useEffect, useRef, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';

function TerminalTab({
  tab,
  active,
  onClick,
  onClose,
}: {
  tab: { id: string; name: string };
  active: boolean;
  onClick: () => void;
  onClose: () => void;
}) {
  return (
    <span
      className={`term-tab${active ? ' active' : ''}`}
      style={{ padding: '4px 12px', cursor: 'pointer', background: active ? '#23272e' : 'none', borderRadius: 4, marginRight: 4, display: 'inline-flex', alignItems: 'center' }}
      onClick={onClick}
    >
      {tab.name}
      <span className="codicon codicon-close" style={{ marginLeft: 6, fontSize: 14 }} onClick={e => { e.stopPropagation(); onClose(); }}></span>
    </span>
  );
}

export default function TerminalMultiTab() {
  const [tabs, setTabs] = useState<{ id: string; name: string }[]>([
    { id: uuidv4(), name: 'Terminal 1' },
  ]);
  const [activeTab, setActiveTab] = useState(0);
  const xtermRefs = useRef<(HTMLDivElement | null)[]>([]);
  const termInstances = useRef<any[]>([]);
  const [outputs, setOutputs] = useState<string[]>(['']);
  const [loading, setLoading] = useState(false);
  const [termHeight, setTermHeight] = useState(200);
  const resizing = useRef(false);
  const startY = useRef(0);
  const startHeight = useRef(200);

  // Remove the WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW thing by hiding the xterm-char-measure-element
  useEffect(() => {
    const style = document.createElement('style');
    style.innerHTML = `.xterm-char-measure-element { display: none !important; }`;
    document.head.appendChild(style);
    return () => { document.head.removeChild(style); };
  }, []);

  useEffect(() => {
    // Only create terminals for visible tabs
    xtermRefs.current.forEach(async (ref, i) => {
      if (!ref) return;
      // If terminal instance already exists, skip
      if (termInstances.current[i] && ref.querySelector('.xterm')) return;
      const XTerm = (await import('xterm')).Terminal;
      const FitAddon = (await import('xterm-addon-fit')).FitAddon;
      const fitAddon = new FitAddon();
      const term = new XTerm({
        theme: { background: '#1e1e1e', foreground: '#d4d4d4' },
        fontSize: 14,
        rows: 10,
        fontFamily: 'Fira Mono, Consolas, monospace',
        cursorBlink: true,
        allowProposedApi: true,
        windowsMode: false,
        cols: 80,
        scrollback: 1000,
      });
      term.loadAddon(fitAddon);
      term.open(ref);
      fitAddon.fit();
      // Prompt and shell output formatting
      function prompt(term: any, cwd: string) {
        term.write(`\r\n${cwd} $ `);
      }
      let cwd = '/';
      prompt(term, cwd);
      let command = '';
      term.onKey(async e => {
        const ev = e.domEvent;
        const printable = !ev.altKey && !ev.ctrlKey && !ev.metaKey;
        if (ev.keyCode === 13) { // Enter
          term.write('\r\n');
          if (command.trim()) {
            setLoading(true);
            const res = await fetch('/api/terminal', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ tabId: tabs[i].id, input: command + '\n' }),
            });
            const data = await res.json();
            term.write(data.output);
            setLoading(false);
          }
          command = '';
          prompt(term, cwd);
        } else if (ev.keyCode === 8) { // Backspace
          if (command.length > 0) {
            term.write('\b \b');
            command = command.slice(0, -1);
          }
        } else if (printable) {
          command += e.key;
          term.write(e.key);
        }
      });
      termInstances.current[i] = term;
    });
    // eslint-disable-next-line
  }, [tabs, activeTab]);

  // Add new terminal tab
  function handleAddTab() {
    setTabs(tabs => [...tabs, { id: uuidv4(), name: `Terminal ${tabs.length + 1}` }]);
    setOutputs(outputs => [...outputs, '']);
    setActiveTab(tabs.length);
  }
  // Remove terminal tab
  function handleCloseTab(idx: number) {
    const tabId = tabs[idx].id;
    fetch('/api/terminal', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tabId }),
    });
    setTabs(tabs => tabs.filter((_, i) => i !== idx));
    setOutputs(outputs => outputs.filter((_, i) => i !== idx));
    if (activeTab >= idx && activeTab > 0) setActiveTab(activeTab - 1);
  }

  // Terminal resize handlers (vertical drag)
  function handleResizeStart(e: React.MouseEvent) {
    resizing.current = true;
    startY.current = e.clientY;
    startHeight.current = termHeight;
    document.body.style.cursor = 'ns-resize';
    window.addEventListener('mousemove', handleResizeDrag, { passive: false });
    window.addEventListener('mouseup', handleResizeEnd, { passive: false });
    e.preventDefault();
    e.stopPropagation();
  }
  function handleResizeDrag(e: MouseEvent) {
    if (!resizing.current) return;
    e.preventDefault();
    // Invert the direction: dragging up should decrease height, down should increase
    let newHeight = startHeight.current - (e.clientY - startY.current);
    if (newHeight < 120) newHeight = 120;
    if (newHeight > 600) newHeight = 600;
    setTermHeight(newHeight);
  }
  function handleResizeEnd(e?: MouseEvent) {
    resizing.current = false;
    document.body.style.cursor = '';
    window.removeEventListener('mousemove', handleResizeDrag);
    window.removeEventListener('mouseup', handleResizeEnd);
    if (e) e.preventDefault();
  }

  return (
    <div id="terminal-outer-panel" style={{ background: '#1e1e1e', borderTop: '1px solid #222', width: '100%', minHeight: 120, display: 'flex', flexDirection: 'column', height: termHeight + 34, userSelect: resizing.current ? 'none' : 'auto' }}
      onMouseDown={e => {
        // Only start resize if the event is at the very top (from parent resizer)
        if (e.nativeEvent.offsetY <= 10) {
          handleResizeStart(e);
        }
      }}
    >
      <div id="terminal-tabs" style={{ display: 'flex', alignItems: 'center', padding: '4px 8px', borderBottom: '1px solid #222', minHeight: 34 }}>
        {tabs.map((tab, i) => (
          <TerminalTab
            key={tab.id}
            tab={tab}
            active={i === activeTab}
            onClick={() => setActiveTab(i)}
            onClose={() => handleCloseTab(i)}
          />
        ))}
        <span className="codicon codicon-add" id="add-terminal-btn" style={{ marginLeft: 8, cursor: 'pointer', fontSize: 18 }} onClick={handleAddTab}></span>
      </div>
      <div
        id="terminal-container"
        style={{ width: '100%', flex: 1, background: '#1e1e1e', position: 'relative', transition: 'height 0.18s cubic-bezier(.4,2,.6,1)', overflow: 'hidden', borderBottom: '1px solid #222', minHeight: 80 }}
        onClick={() => {
          // Focus the terminal when clicking anywhere in the terminal container
          const textarea = xtermRefs.current[activeTab]?.querySelector?.('textarea');
          if (textarea) textarea.focus();
        }}
      >
        {tabs.map((tab, i) => (
          <div
            key={tab.id}
            style={{ display: i === activeTab ? 'block' : 'none', width: '100%', height: '100%' }}
            ref={el => {
              xtermRefs.current[i] = el;
              return undefined;
            }}
            tabIndex={0}
          />
        ))}
        {loading && <div style={{ position: 'absolute', top: 8, right: 16, color: '#fff', fontSize: 12 }}>Running...</div>}
      </div>
    </div>
  );
}
